CREATE DATABASE IF NOT EXISTS it_books CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE it_books;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS order_items; DROP TABLE IF EXISTS orders; DROP TABLE IF EXISTS posts; DROP TABLE IF EXISTS books; DROP TABLE IF EXISTS categories; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',status ENUM('active','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description TEXT NULL) ENGINE=InnoDB;
CREATE TABLE books(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,title VARCHAR(255) NOT NULL,code VARCHAR(50) NOT NULL,author VARCHAR(180) NOT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,description TEXT NULL,cover_image VARCHAR(255) NULL,publisher VARCHAR(180) NULL,publish_year SMALLINT NULL,pages SMALLINT UNSIGNED NULL,language VARCHAR(60) NULL,isbn VARCHAR(30) NULL,file_path VARCHAR(255) NULL,status ENUM('active','deleted') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,INDEX(title),INDEX(code)) ENGINE=InnoDB;
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,customer_name VARCHAR(150) NOT NULL,phone VARCHAR(30) NOT NULL,address TEXT NOT NULL,total DECIMAL(12,2) NOT NULL,status ENUM('pending','processing','shipping','completed','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,book_id INT NULL,book_title VARCHAR(255) NOT NULL,price DECIMAL(12,2) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE posts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,content TEXT NOT NULL,status ENUM('published','hidden') NOT NULL DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
